// Prepare Input v2.1: form + QA feedback merge, deterministic IoC extraction.
// URLs are reduced to their hostname (VT returns 404 for never-scanned URLs).
// Reserved TLDs and private IPs are dropped before reaching the agent.
const form = $('Form Trigger').first().json;
const incoming = $input.first().json || {};
const isRetry = incoming.status === 'REJECTED';
const attempt = isRetry ? (Number(incoming.attempt) || 1) + 1 : 1;
const feedback = isRetry ? String(incoming.feedback || '') : null;

let text = String(form['Suspicious Text'] || '').trim();
if (text.length > 4000) text = text.slice(0, 4000) + ' [truncated]';
const known = String(form['Known IoC'] || '').trim();

const ipRe  = /\b(?:(?:25[0-5]|2[0-4]\d|1?\d?\d)\.){3}(?:25[0-5]|2[0-4]\d|1?\d?\d)\b/g;
const urlRe = /https?:\/\/[^\s"'<>)\]]+/gi;
const domRe = /\b(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,10}\b/gi;

const RESERVED_TLD = new Set(['example','test','invalid','localhost','local','internal','lan','home','corp']);
const NOT_DOMAINS  = /\.(png|jpg|jpeg|gif|js|css|html|htm|pdf|json|xml|txt)$/i;

const isPrivateIp = ip => {
  const [a, b] = ip.split('.').map(Number);
  return a === 10 || a === 127 || a === 0 || (a === 172 && b >= 16 && b <= 31) || (a === 192 && b === 168) || (a === 169 && b === 254);
};
const isValidDomain = d => {
  const tld = d.split('.').pop().toLowerCase();
  return !RESERVED_TLD.has(tld) && !NOT_DOMAINS.test(d) && d.includes('.');
};
const hostOf = u => { try { return new URL(u).hostname.toLowerCase(); } catch { return null; } };

const seen = new Set(); const iocs = []; const dropped = [];
const push = (value, type) => {
  const v = value.trim().replace(/[.,;:)\]]+$/, '').toLowerCase();
  if (!v || seen.has(v)) return;
  if (type === 'ip') {
    if (isPrivateIp(v)) { dropped.push({ value: v, reason: 'private/reserved IP' }); return; }
    seen.add(v); iocs.push({ value: v, type: 'ip', vt_path: 'ip_addresses/' + v }); return;
  }
  if (type === 'domain') {
    if (!isValidDomain(v)) { dropped.push({ value: v, reason: 'reserved TLD or not a domain' }); return; }
    seen.add(v); iocs.push({ value: v, type: 'domain', vt_path: 'domains/' + v });
  }
};

if (known) {
  ipRe.lastIndex = 0;
  if (ipRe.test(known)) push(known, 'ip');
  else if (/^https?:\/\//i.test(known)) { const h = hostOf(known); if (h) push(h, 'domain'); }
  else push(known, 'domain');
}
(text.match(urlRe) || []).forEach(u => { const h = hostOf(u); if (!h) return; ipRe.lastIndex = 0; push(h, ipRe.test(h) ? 'ip' : 'domain'); ipRe.lastIndex = 0; });
(text.match(ipRe)  || []).forEach(ip => push(ip, 'ip'));
(text.match(domRe) || []).forEach(d => push(d, 'domain'));

// VirusTotal public API: 4 req/min. Cap to 3 per run.
const capped = iocs.slice(0, 3);
const urlsFound = (text.match(urlRe) || []);

const injRe = /(ignore|disregard|override|forget)\s+(all\s+|the\s+|any\s+)?(previous|prior|above|earlier)\s+(instructions?|rules?|prompts?)|system\s*(note|prompt)?\s*:|you are now|as an ai|new instructions?|assistant\s*:|<\s*img|\{\{.*\}\}|\bexfil|send (all|the) (contacts?|emails?|data)|append .* (email|contact)/i;

return [{ json: {
  attempt, max_attempts: 3, feedback,
  text, known_ioc: known || null,
  iocs: capped,
  dropped_iocs: dropped.concat(iocs.slice(3).map(i => ({ value: i.value, reason: 'rate-limit cap' }))),
  urls_in_text: urlsFound,
  injection_hint: injRe.test(text),
  received_at: new Date().toISOString()
}}];

// Rule Validator: deterministic syntax checks on Agent B output. No LLM involved.
const raw = $input.first().json.output ?? '';

function parseJson(s) {
  if (s && typeof s === 'object') return s;
  const clean = String(s).replace(/```json/gi, '').replace(/```/g, '').trim();
  const a = clean.indexOf('{'), b = clean.lastIndexOf('}');
  if (a === -1 || b === -1) throw new Error('No JSON object found in Agent B output');
  return JSON.parse(clean.slice(a, b + 1));
}

const errors = [];
let report = {};
try { report = parseJson(raw); } catch (e) { errors.push('Agent B output is not valid JSON: ' + e.message); }

const sev = String(report.Severity || '').toUpperCase();
if (!['LOW','MEDIUM','HIGH','CRITICAL'].includes(sev)) errors.push('Severity missing or not in LOW/MEDIUM/HIGH/CRITICAL');
if (!Array.isArray(report.Blue_Team_Recommendations) || report.Blue_Team_Recommendations.length < 3) errors.push('Fewer than 3 Blue Team recommendations');

// --- Snort ---
const snort = String(report.Snort_Rule || '').trim();
let snort_ok = false;
if (snort === 'NONE') { snort_ok = true; }
else {
  const header = /^(alert|log|pass|drop|reject)\s+(tcp|udp|icmp|ip|http)\s+\S+\s+\S+\s+(->|<>)\s+\S+\s+\S+\s+\((.*)\)\s*$/s;
  const m = snort.match(header);
  if (!m) errors.push('Snort rule header malformed');
  else {
    const opts = m[4];
    if (!/msg:"[^"]+";/.test(opts)) errors.push('Snort rule missing msg');
    const sid = opts.match(/sid:(\d+);/);
    if (!sid) errors.push('Snort rule missing sid');
    else if (Number(sid[1]) < 1000000) errors.push('Snort sid must be >= 1000000 (local rule range)');
    if (!/rev:\d+;/.test(opts)) errors.push('Snort rule missing rev');
    if (/\n/.test(snort)) errors.push('Snort rule must be a single line');
    snort_ok = errors.filter(e => e.startsWith('Snort')).length === 0;
  }
}

// --- YARA ---
const yara = String(report.YARA_Rule || '').trim();
let yara_ok = false;
if (yara === 'NONE') { yara_ok = true; }
else {
  if (!/^rule\s+[A-Za-z_][A-Za-z0-9_]*\s*\{/.test(yara)) errors.push('YARA rule must start with: rule <Name> {');
  if (!/condition\s*:/.test(yara)) errors.push('YARA rule missing condition:');
  const opens = (yara.match(/\{/g) || []).length, closes = (yara.match(/\}/g) || []).length;
  if (opens !== closes) errors.push('YARA rule braces unbalanced');
  if (/strings\s*:/.test(yara) && !/\$[A-Za-z0-9_]+\s*=/.test(yara)) errors.push('YARA strings section declared but no $identifier = defined');
  yara_ok = errors.filter(e => e.startsWith('YARA')).length === 0;
}

// --- Hallucination tripwires ---
const blob = JSON.stringify(report);
if (/CVE-\d{4}-\d+/i.test(blob)) errors.push('Report contains CVE identifiers; source APIs do not return CVEs');
if (/\b\d{1,3}\s?%\s*(probability|likelihood|chance)/i.test(blob)) errors.push('Report contains fabricated probability statements');

return [{ json: {
  validator: { snort_ok, yara_ok, errors, checked_at: new Date().toISOString() },
  report
}}];

// QA Router: parses Agent C verdict. FAIL-CLOSED. Never force-approves.
const cOut = $input.first().json.output ?? '';
const prep = $('Prepare Input').first().json;
const val  = $('Rule Validator').first().json;
const aOut = $('Agent A (Ingestion)').first().json.output ?? '';
const dOut = $('Agent D (MITRE Mapping)').first().json.output ?? '';

function parseJson(s) {
  if (s && typeof s === 'object') return s;
  const clean = String(s).replace(/```json/gi, '').replace(/```/g, '').trim();
  const a = clean.indexOf('{'), b = clean.lastIndexOf('}');
  if (a === -1 || b === -1) return null;
  try { return JSON.parse(clean.slice(a, b + 1)); } catch { return null; }
}

const verdict = parseJson(cOut) || {};
let status = verdict.status === 'APPROVED' ? 'APPROVED' : 'REJECTED';
let feedback = String(verdict.feedback || '');
if (!verdict.status) feedback = 'QA agent returned unparseable output. ' + feedback;

// v2.2: empty or unparseable Agent A output is a pipeline fault, never a LOW finding (fail-closed).
const aParsed = parseJson(aOut);
if (!aParsed || aParsed.Injection_Suspected === undefined || aParsed.Injection_Suspected === null) {
  status = 'REJECTED';
  feedback = 'Agent A produced no usable output (empty or unparseable JSON). Re-run ingestion. ' + feedback;
}

// Validator errors override the LLM verdict (deterministic wins).
if (val.validator && val.validator.errors.length) {
  status = 'REJECTED';
  feedback = 'Validator errors: ' + val.validator.errors.join('; ') + (feedback ? ' | QA: ' + feedback : '');
}

const attempt = Number(prep.attempt) || 1;
const max = Number(prep.max_attempts) || 3;
if (status === 'REJECTED' && attempt >= max) {
  status = 'FAILED_MAX_ATTEMPTS';
  feedback = `Halted after ${attempt} attempts. Last feedback: ` + feedback;
}

const r = val.report || {};
const sevMap = { CRITICAL: 'High', HIGH: 'High', MEDIUM: 'Medium', LOW: 'Low' };
const sev = String(r.Severity || 'MEDIUM').toUpperCase();

return [{ json: {
  status, feedback, attempt, max_attempts: max,
  target: (() => { const t = (parseJson(aOut) || {}).Target; if (t && t !== 'text-only') return t; const f = (prep.iocs || [])[0]; return f ? f.value : (prep.known_ioc || 'text-only'); })(),
  severity: sev,
  sf_priority: sevMap[sev] || 'Medium',
  injection_suspected: (parseJson(aOut) || {}).Injection_Suspected ?? null,
  risk_assessment: r.Risk_Assessment || '',
  recommendations: r.Blue_Team_Recommendations || [],
  snort_rule: r.Snort_Rule || 'NONE',
  yara_rule: r.YARA_Rule || 'NONE',
  sf_hardening: r.Salesforce_Hardening || [],
  mitre: parseJson(dOut) || {},
  validator: val.validator,
  agent_a: parseJson(aOut) || {},
  execution_id: $execution.id,
  finished_at: new Date().toISOString()
}}];

